#include <stdio.h>
#include <stdlib.h>

FILE *open_file(const char *path, const char *mode) {
    FILE *file = fopen(path, mode);
    if (!file) { perror(path); exit(1); }
    return file;
}
void show_file(const char *path) {
    FILE *file = open_file(path, "r");
    int ch;
    while ((ch = fgetc(file)) != EOF) putchar(ch);
    fclose(file);
}
void copy_file(const char *source, const char *target) {
    FILE *in = open_file(source, "rb"), *out = open_file(target, "wb");
    int ch;
    while ((ch = fgetc(in)) != EOF) fputc(ch, out);
    fclose(in); fclose(out);
}

typedef struct { int num; char name[32]; double score[3]; } Student;
double average(const Student *student) { return (student->score[0] + student->score[1] + student->score[2]) / 3; }
void read_students(Student *a, int n) {
    for (int i = 0; i < n; i++) scanf("%d%31s%lf%lf%lf", &a[i].num, a[i].name, &a[i].score[0], &a[i].score[1], &a[i].score[2]);
}
void print_student(const Student *s) {
    printf("%d %s %.2f %.2f %.2f", s->num, s->name, s->score[0], s->score[1], s->score[2]);
}

int main(void) {
    Student students[5];
    read_students(students, 5);
    FILE *file = open_file("stud", "w");
    for (int i = 0; i < 5; i++) fprintf(file, "%d %s %.2f %.2f %.2f %.2f\n", students[i].num, students[i].name, students[i].score[0], students[i].score[1], students[i].score[2], average(&students[i]));
    fclose(file);
    show_file("stud");
    return 0;
}
